41	const PROCESSING_FEE = 5;
42	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
43	
44	const BASE_PREMIUMS: Record<string, number> = {
45	  sword: 100,
46	  amulet: 60,
47	  staff: 80,
48	  potion: 40,
49	  rune: 25,
50	  moonstone: 25,
51	};
52	
53	/** Premiums round up: fractions of a Gold piece go to the MHPCO, never the customer. */
54	const roundPremiumInMHPCOFavour = (amount: number): number => Math.ceil(amount);
55	
56	const COMPONENT_BLOCK_SIZE = 3;
57	const COMPONENT_BLOCK_PREMIUM = 60;
58	
59	const countsByType = (items: Item[]): Map<string, number> =>
60	  items.reduce(
61	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
62	    new Map<string, number>(),
63	  );
64	
65	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
66	
67	/** A group of exactly three alike components is a building block, priced at a flat rate. */
68	const basePremiumForGroup = (type: string, count: number): number =>
69	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE
70	    ? COMPONENT_BLOCK_PREMIUM
71	    : count * BASE_PREMIUMS[type];
72	
73	const policyBasePremiumOf = (items: Item[]): number =>
74	  [...countsByType(items)].reduce(
75	    (total, [type, count]) => total + basePremiumForGroup(type, count),
76	    0,
77	  );
78	
79	const quote = (step: QuoteStep): StepResult => {
80	  const policyBasePremium = policyBasePremiumOf(step.items);
81	  return {
82	    premium: roundPremiumInMHPCOFavour(
83	      policyBasePremium +
84	        policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE +
85	        PROCESSING_FEE,
86	    ),
87	  };
88	};
89	
90	const runStep = (step: Step): StepResult => {
91	  if (step.op === "quote") return quote(step);
92	  throw new Error(`Unsupported step: ${step.op}`);
93	};
94	
95	export const runScenario = (scenario: Scenario): ScenarioResult => ({
96	  results: scenario.steps.map(runStep),
97	});
