/** Policy-wide modifiers are rates on the policy base premium, not on each other. */
const applyRate = (basePremium: number, rate: number): number => basePremium * rate;

const quote = (step: QuoteStep): StepResult => {
  const base = policyBasePremium(step.items);
  return {
    premium: roundPremiumInMHPCOFavour(
      base + applyRate(base, INITIAL_ASSESSMENT_SURCHARGE) + PROCESSING_FEE,
    ),
  };
};
